-- Migración aditiva Margen Personal: presupuestos, metas, pasivos y recurrencias.
create table if not exists public.budget_limits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null check(char_length(category) between 1 and 80),monthly_limit_eur numeric(14,2) not null check(monthly_limit_eur>0),created_at timestamptz not null default now(),unique(user_id,category));
create table if not exists public.savings_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_amount_eur numeric(14,2) not null check(target_amount_eur>0),current_amount_eur numeric(14,2) not null default 0 check(current_amount_eur>=0),target_date date,created_at timestamptz not null default now());
create table if not exists public.liabilities(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,debt_type text not null default 'Otra deuda',outstanding_eur numeric(14,2) not null check(outstanding_eur>=0),apr_percent numeric(7,3) not null default 0 check(apr_percent>=0),monthly_payment_eur numeric(14,2) not null default 0 check(monthly_payment_eur>=0),created_at timestamptz not null default now());
create table if not exists public.recurring_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,amount_eur numeric(14,2) not null check(amount_eur>0),category text not null,frequency text not null check(frequency in('Mensual','Anual','Semanal','Trimestral')),day_of_month integer check(day_of_month between 1 and 31),created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['budget_limits','savings_goals','liabilities','recurring_items'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists %I on public.%I',t||'_own',t);execute format('create policy %I on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t||'_own',t);execute format('revoke all on public.%I from anon',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);end loop;end $$;